solution:
interface Commande {
  client: string;
  total: number;
}

function estCommande(x: unknown): x is Commande {
  return typeof x === "object" && x !== null
    && typeof (x as Commande).client === "string"
    && typeof (x as Commande).total === "number";
}

function importer(texte: string): { commandes: Commande[]; rejetees: number } {
  let donnees: unknown;
  try {
    donnees = JSON.parse(texte);
  } catch {
    throw new Error("JSON invalide");
  }
  if (!Array.isArray(donnees)) throw new Error("liste attendue");
  const commandes = donnees.filter(estCommande);
  return { commandes, rejetees: donnees.length - commandes.length };
}
